    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'PKCE-t használ, és nem kap titkot — így nincs mi kiszivárogjon a böngészőből vagy a telefonról.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Mostantól ellenőrzés nélkül fogadjuk az eseményeit — szigorú módban viszont elutasítjuk őket.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Tagjai újra bejelentkezhetnek, környezetei pedig folytatják a hitelesítési szolgáltatást.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Saját hitelesítő adatai a környezet ehhez a szolgáltatóhoz tartozó adatai helyett.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Kulcs létrehozva. Illessze be a frontendbe — szándékosan nyilvános.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Kulcs lecserélve — másolja ki most az újat. A régi kulcs még 24 órán át működik.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'A bejelentkezési oldalon Google-, GitHub-, Apple- és más szolgáltatói gombokat kínál azoknak, akik új jelszó helyett meglévő fiókjukat használnák. A szolgáltatót elég egyszer beállítani a környezethez, és minden szervezet használhatja. Egy szervezet saját hitelesítő adatokat is megadhat, vagy kikapcsolhatja az adott szolgáltatót. Csak a hitelesítő adatokat kell megadni; a többi mező automatikusan kitöltődik. A szolgáltatótól kapott e-mail-cím önmagában soha nem elegendő egy itt már létező fiók eléréséhez.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'A kód által a Cbox ID számára bemutatott kulcsok, típusonként külön lapon. A titkos kulcs, más néven felügyeleti kulcs lehetővé teszi a háttérrendszernek egy környezet szervezeteinek, tagjainak, meghívásainak, szerepköreinek és alkalmazásainak kezelését. A szervezet kulcsa beépített szerepkörrel hívja a szervezet API-ját. A közzétehető kulcs böngészős alkalmazásba kerül, és csak az engedélyezett eredetekről működik. A titkos és szervezeti kulcsok csak egyszer jelennek meg: létrehozáskor másolja ki őket, kiszivárgáskor pedig azonnal vonja vissza.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Olyan alkalmazásokat regisztrál, amelyek ezt a környezetet fogadják el SAML-identitásszolgáltatóként, így a felhasználók meglévő itteni fiókjukkal jelentkezhetnek be. Minden alkalmazáshoz hozzárendelhető a saját szervezete; ekkor csak annak tagjai léphetnek be. Szervezet nélkül az alkalmazás a környezet minden felhasználója számára elérhető. Ez a kimenő irány. Más rendszerben lévő vállalati fiókkal történő bejelentkezéshez a Hitelesítés alatti Vállalati SSO használható.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'A használt keretrendszer kiválasztása után létrejön egy alkalmazás a helyi fejlesztői szerverre mutató átirányítással, a beilleszthető környezeti konfigurációval és a bejelentkeztető kóddal. Az oldal megvárja az első tényleges bejelentkezést. Alatta a termék előkészítésének lépései láthatók: arculat, szervezetek, egyszeri bejelentkezés, ügynök, munkatárs és éles környezet. A lépések teljesítését a környezet tényleges állapota jelzi, nem kézi kipipálás.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'A Radar minden bejelentkezést és regisztrációt értékel: lopott hitelesítő adatokkal végzett próbálkozások, botszerű sebesség, lehetetlen helyváltoztatás, új eszközök, anonimizáló hálózatok és eldobható címek, valamint saját szabályok, engedélyezési és tiltólisták alapján. Minden döntést rögzít, és az érvényesítés bekapcsolása után blokkol vagy második hitelesítési tényezőt kér. Itt érdemes áttekinteni a döntéseket az érvényesítés bekapcsolása előtt, illetve ha valaki nem tud bejelentkezni.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Funkciókapcsolók, amelyek állapotát az alkalmazások egy adott szervezet adott személyére kérdezik le. Kapcsoljon be egy funkciót kijelölt felhasználóknak, szervezeteknek vagy az összes felhasználó egy részének. Minden alkalmazás ugyanazt a választ olvassa ki a tokenből vagy az API-ból.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Szoftverek, amelyek kezelési kulccsal végeznek műveleteket ebben a környezetben: Claude Code, Cursor, belső bot vagy saját backend. Mindegyik csak a megadott jogosultsági hatókörökkel rendelkezik, és ahol Ön előírta, megvárja a jóváhagyását.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'A fogadó rendszer ugyanazt a titkos kulcsot használja. A 64 karakteres hexadecimális titkos kulcsból whsec_ és a hexadecimális szöveg base64-kódolása lesz: "whsec_" + base64(secret). A már whsec_ kezdetű titkos kulcs változatlanul használható.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'A telepítés összes környezetének szervezetei, felhasználói és aktív munkamenetei, valamint a legtöbb taggal rendelkező szervezetek. Ez a nézet csak adatokat olvas, és soha nem változtatja meg a konzolban kiválasztott környezetet.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Mindenki, aki bejelentkezhet ebbe a szervezetbe, valamint az elküldött, még el nem fogadott meghívók. Hívjon meg embereket e-mailben; a bejelentkezést maguk állítják be, így Önnek soha nem kell más jelszavát kezelnie.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Tegye lehetővé a bejelentkezést már meglévő fiókkal. A szolgáltatót egyszer állítsa be a környezethez, és minden szervezetben elérhető lesz. A szervezetek saját hitelesítő adatokat használhatnak, vagy letilthatnak egy szolgáltatót.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'A Radar minden bejelentkezést és regisztrációt kiértékel: lopott hitelesítő adatokkal végzett próbálkozások, botokra jellemző sebesség, lehetetlen helyváltoztatás, új eszközök, anonimizáló hálózatok, eldobható címek, valamint saját szabályok és listák alapján. A döntés okát is rögzíti.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Ez a felhasználó többé nem jelentkezhet be a környezet egyik alkalmazásába sem, és meglévő munkamenetei a következő kérésnél érvénytelenné válnak. Az adatai megmaradnak, és bármikor újraaktiválhatja.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'A kiértékelés sorrendje: tiltólista, engedélyezési lista, saját szabályok felülről lefelé (az első egyezés dönt), majd beépített szabályok (az érvényesülő szabályok közül a legszigorúbb dönt). Ha nincs egyezés, a hozzáférés engedélyezett.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'A legtöbb integrációhoz webhookot érdemes használni: ezek az esemény után futnak, és nem akadályozhatják a műveletet. Hookot csak akkor használjon, ha saját rendszerének a bejelentkezés vagy a token kiadása közben kell beleszólnia a folyamatba.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Itt jelennek meg a létrehozott kulcsok az utolsó használatuk időpontjával.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Zárolás nélkül hagyja üresen — ezen a telepítésen az alapértelmezett zárolás ki van kapcsolva.',
