    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Amit a kódja kér, és amit a feature_flags claim tartalmaz. Kisbetűk és számjegyek, közöttük - _ vagy . jelekkel. Később nem módosítható.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Minden, ami ezt a kulcsot használja, azonnal leáll. Ez nem vonható vissza.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Minden azonnal leáll, amibe a birtokos ezt a kulcsot beállította. Ha lehet, előbb értesítse. Ez nem vonható vissza.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Ha valaki API-kulcsot hoz létre valamelyik alkalmazásához, itt megjelenik a birtokosa és az engedélyezett műveletei.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Ha valaki kijelentkezik, vagy egy adminisztrátor lezárja a munkameneteit, eltávolítja vagy inaktiválja, a Cbox ID aláírt kijelentkezési tokent küld erre a címre közvetlenül a kiszolgálók között, hogy az alkalmazás is lezárhassa saját munkamenetét.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Ide irányítja a Cbox ID a személyeket az alkalmazásból való kijelentkezés után. Az alkalmazás által kért URI-nak karakterre pontosan meg kell egyeznie egy itt megadott URI-val, a záró perjelet is beleértve. Ellenkező esetben a Cbox ID a saját kijelentkezési oldalán tartja a személyt. Hagyja üresen, ha az alkalmazás kijelentkezés után nem irányít át senkit.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Az a cím, ahol az alkalmazás közzéteszi az ismert szerepköreit, hogy ezen az oldalon hozzárendelhetők legyenek.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Milyen bejelentkezési módokat kínál :part1 a jelszón kívül, és meddig tart a bejelentkezés. Ezek a környezet minden szervezetében azonosak.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Kik tartoznak a szervezethez, és mit tehetnek. Akinek még nincs itt fiókja, e-mailes meghívót kap.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Ki kapja meg a funkciójelzőt, ha egyetlen szabály sem nevezi meg. Hagyja kikapcsolva, hogy először megnevezett szervezeteknél vagy a felhasználók adott százalékánál vezesse be.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Kié a szerepkör — vagy jelölje be a fenti négyzetet, hogy minden szervezetre definiálja.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Kinek a szerepköreit és tagságait rögzíti a felülvizsgálat.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Kié a szabály — vagy jelölje be a fenti négyzetet, hogy minden szervezetre alkalmazza.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Szerepkörök nélkül minden bejelentkezni képes személy azt a hozzáférést kapja, amelyet az alkalmazás egy egyszerű felhasználónak ad. Egy szerepkörrel egyszer határozhatja meg, hogy kik szerkesztők és kik ügyfélszolgálati munkatársak, és ezt minden csatlakoztatott alkalmazás figyelembe veszi.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Haladjon végig a listán: igazolja, ami még szükséges, és vonja vissza, ami nem.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Írjon be egyet fent, vagy küldje őket az alkalmazás háttérrendszeréből legfeljebb 100-as csoportokban.',
    'writes_531995e8' => 'írás',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Ön az egyetlen tulajdonos. Előbb adja át a tulajdonjogot valaki másnak, vagy törölje a szervezetet.',
    'you_can_also_part1_part2_part3_53f32513' => 'Másik lehetőség: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Bármikor visszaállíthatja az „SSO előnyben részesítése” vagy a „Mindkettő elérhető” értékre; a lezárt munkamenetek lezárva maradnak.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Bármikor visszaállíthatja az „SSO előnyben részesítése” vagy a „Mindkettő elérhető” értékre; a lezárt munkamenetek lezárva maradnak.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Azonnal elveszíti a hozzáférést. Tulajdonosként csak akkor léphet ki, ha már más a tulajdonos. Előbb adja át a tulajdonjogot, vagy törölje a szervezetet a Beállítások alatt.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Azonnal elveszíti a hozzáférést ehhez a szervezethez és alkalmazásaihoz. Egy adminisztrátor újra meghívhatja.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Az alkalmazás saját hozzáférési modellje: erőforrástípusok, az egyes típusok kapcsolatai és azok öröklődése. Az alkalmazás kapcsolati rekordokat ír arról, hogy ki mihez kapcsolódik, és minden kérésnél ellenőrzi a hozzáférést.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'A hitelesítési szabályzata továbbra is érvényes: jelszóerősség, adatszivárgás-ellenőrzés, e-mail-megerősítés, gyakorisági korlátok és botellenőrzések.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'A saját API-ja. Hatókörönként döntheti el, melyiket kérhetik a szervezetek által regisztrált alkalmazások.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'A bejelentkezési oldal „Fiók létrehozása” hivatkozást kap, és az alkalmazások a :part1 használatával közvetlenül a regisztrációhoz küldhetik a felhasználókat.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'A tokenben szereplő szerepkörök és jogosultságok pillanatfelvételt jelentenek. Minden védett művelet előtt kérjen aktuális hozzáférési döntést a Cbox ID-tól, és az alkalmazásban ellenőrizze a konkrét erőforráshoz való hozzáférést. A token tartalma önmagában nem tükrözi a későbbi visszavonásokat:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Saját bejelentkezési módjai és aktív munkamenetei. A hozzáférési kulcs a legbiztonságosabb és leggyorsabb megoldás: az eszköz ujjlenyomattal vagy arcfelismeréssel oldja fel, és nem marad adathalászattal megszerezhető jelszó.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Minden műveletet úgy fogadunk el, ahogy az alkalmazás elküldi. Adjon sémát egy művelethez, hogy eseményeit beérkezéskor ellenőrizzük. A napló következetességét az esemény írásakor kell biztosítani, nem az olvasásakor.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Az alkalmazás konfigurációjában vagy környezeti fájljában tárolt API-kulcsokat nem tudja központilag lecserélni vagy gyorsan visszavonni. Az itt tárolt kulcs titkosított, alkalmazásonként engedélyezhető, és egy kattintással visszavonható.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'A gomb többé nem jelenik meg, és a hitelesítő adatok törlődnek. Akik ezzel a szolgáltatóval jelentkeztek be, megtartják fiókjukat, és továbbra is használhatják a jelszavukat. Ha meg szeretné tartani a hitelesítő adatokat, törlés helyett tiltsa le a szolgáltatót.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'A fordított irány: a Cbox ID átadja a munkatársakat a vállalat által használt más SaaS-termékeknek azok SCIM-végpontjain keresztül. Egyetlen helyen adhat és vonhat vissza hozzáférést, ahelyett hogy minden szolgáltató külön adminisztrációs felületét használná.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Létrehozza a szervezetet, annak tulajdonosát, első termékét és a termék éles környezetét. A tulajdonos e-mailben kap hivatkozást saját jelszava beállításához; Ön nem választ helyette jelszót.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Jelenleg valaki kézzel ad hozzá és távolít el embereket ezen a felületen. Csatlakoztassa a vállalat által már karbantartott címtárat, és mindkét feladat automatikussá válik, beleértve az eltávolításokat is, amelyekről a legkönnyebb megfeledkezni.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Az összes általa kiadott tokent most visszavonjuk, és új bejelentkezéshez már nem használható. A tokeneket önállóan ellenőrző alkalmazás a lejáratukkor nem fogadja el őket többé, legkésőbb a munkamenet végén.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Amíg másik rendszerről költözik át, az alkalmazás a jegyzékében, a szerepkörök mellett megadhatja régi bejelentkezési felületének helyét. Ez itt jóváhagyásra megjelenik, mielőtt bármit végrehajtana.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Írjon szabályt, amely a felhasználókról ismert adatok alapján engedélyez, további ellenőrzést kér vagy tilt. Kérjen további ellenőrzést az olyan országokból érkező bejelentkezéseknél, ahol nem működik a cége, vagy mentesítse az irodai hálózatot a gyakorisági szabályok alól.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Saját domainje, például az acme.com igazolásával a Cbox ID e-mail-cím alapján felismeri a munkatársait, és közvetlenül a szolgáltatójához irányítja őket, így senkinek nem kell kiválasztania a megfelelő bejelentkezési gombot.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'A szolgáltató metaadatait importáló identitásszolgáltató ezt az URL-t használja az entitásazonosító és az ACS URL külön megadása helyett. Már az identitásszolgáltató oldali beállítások kitöltése előtt is működik.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Ez a művelet nem vonható vissza. A hitelesítő adatok, tagságok és személyes adatok törlődnek, a fiók pedig álnevesítve lesz. Ha a személy egy szervezet egyetlen tulajdonosa, előbb ruházza át a tulajdonjogot.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'A személy nevében, az ő munkamenetében és hozzáférési jogaival jár el. Ez legfeljebb 30 percig tart, és csak olvasásra jogosít ott, ahol a konzol ezt ki tudja kényszeríteni. Minden kérés az Ön nevéhez kapcsolva kerül naplózásra.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Ezen az oldalon csak a felfüggesztés módosít adatot, és az is visszavonható. Egy környezet kiválasztása és megnyitása csak a konzol nézetét változtatja meg; egyik környezetben sem módosít semmit.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Jelenleg az itt tárolt hitelesítő adatokkal jelentkeznek be a felhasználók. Csatlakoztassa a szolgáltatóját, hogy meglévő vállalati fiókjukat használhassák, és amint ott letiltja azt, itt is elveszítsék a hozzáférést.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Nem jön létre új titkos kulcs. A következő próbálkozástól kezdve, az újrapróbálkozásokat is beleértve, a kézbesítések a másik séma fejléceit tartalmazzák. A nem frissített fogadó rendszer mindegyiket elutasítja.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Küldje el ezt az egyszer használható hivatkozást az identitásszolgáltatójuk üzemeltetőjének, ha nem kapta meg e-mailben. Lejáratáig fiók nélkül is működik. Másolja ki most, mert csak egyszer jelenik meg.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'A környezetben emberi engedélyre váró szoftverek. Az az ügynök, amelynek kulcsa jóváhagyást igényel, megáll, és megkérdezi a kulcs létrehozóját. Válaszoljon itt vagy a telefonján.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'A szervezet fogja össze a felhasználókat, bejelentkezési módokat és szerepköröket. Hozzon létre egyet fent, vagy a Környezetek oldalon állítsa be a környezet első szervezetét és rendszergazdáját.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Adja hozzá a személyt az alábbi szervezetek egyikéhez, hogy azon belül hozzáférést kapjon. Ha alkalmazásai nem különítik el saját maguk a szervezeteket, adjon neki a teljes környezetre érvényes adminisztrációs és támogatási szerepkört.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Az adminisztrációs és támogatási szerepkört saját munkatársainak adja a teljes környezetre. Minden szervezetben érvényes, és egyetlen szervezet rendszergazdái sem láthatják vagy módosíthatják.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'A kérelmek automatikusan megjelennek itt, amikor egy alkalmazás vagy ügynök az Ön jóváhagyását kéri, hogy a nevében járjon el. Addig nincs teendője. Ha olyan kérelem jelenik meg, amelyet nem Ön indított, utasítsa el.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'Az SMS a leggyengébb második tényező: aki átveszi az irányítást a telefonszáma felett, megkapja a kódjait. Részesítse előnyben a hitelesítő alkalmazást vagy a hozzáférési kulcsot, és csak akkor használjon SMS-t, ha ezekre nincs lehetősége.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'A környezet alapértelmezett arculata: a szolgáltatott bejelentkezési oldal megjelenése, logója és faviconja, valamint a felhasználók által látott név és feladó. Minden szervezet ezt örökli, hacsak nem állít be sajátot.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'A szervezet adatai a célkörnyezetben: tagok, SSO, domainek, jogosultságok és legutóbbi tevékenységek. Ezen az oldalon csak a szervezet állapota módosítható.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'A telepítés összes szervezete. Nyisson meg egyet a termékei és környezetei áttekintéséhez. Felfüggesztése kijelentkezteti a tagjait, és leállítja a hitelesítést az összes hozzá tartozó környezetben.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Ezeket az eseményeket az alkalmazása küldi, kötegenként egy hívással; minden esemény megadja, melyik szervezetben történt. Beérkezésükkor itt és az adott szervezet rendszergazdáinál is megjelennek.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'A környezet összes bejelentkezési oldalán elérhető. Válasszon ki egy szervezetet saját szolgáltató beállításához; az a szervezet oldalán a környezet szolgáltatójának helyébe lép.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'A Claude Code megnyitja a böngészőt az itteni bejelentkezéshez, majd megkérdezi, mit engedélyez. Nem kell kulcsot biztonságban tartania. Minden OAuth-tal bejelentkező MCP-kliens ugyanígy működik ezzel az URL-lel.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'A telepítés egyik szervezete: a csapata, projektjei és a projektek összes környezete. Felfüggesztése kijelentkezteti a tagjait, és leállítja a hitelesítést mindezekben a környezetekben.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'A teljes környezetre érvényes: bárki bejelentkezhet az alkalmazásba, akinek fiókja van ebben a környezetben, bármely szervezetből. Adjon meg szervezetet, ha nem ilyen széles hozzáférést szeretne.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Az Entra ID, Okta vagy Google Workspace használatával történő bejelentkezés az Enterprise csomagban érhető el. A szervezet számára való engedélyezéshez forduljon a fiókját kezelő csapathoz.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Hol van bejelentkezve, mi járhat el a nevében, és mi történt a fiókjával. Ha ismeretlen dolgot lát, zárja be az érintett munkamenetet, és változtassa meg a jelszavát.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Hányan jelentkeztek be, és milyen gyakran hívták alkalmazásai az API-t az elmúlt 30 napban. Ezek az adatok a terhelés és a rendellenességek megfigyelésére szolgálnak; ez nem számla.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Ez a felhasználó egy szervezet tulajdonosa vagy rendszergazdája, ezért nem lehet belépni a nevében. Egy ilyen fiók átvétele tartós irányítást adhatna a szervezet felett annak, aki ezt megteszi.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-kulcsok, amelyeket alkalmazásai és ügynökei más szolgáltatásoknak mutatnak be. Minden érték titkosítva tárolódik, csak az engedélyezett alkalmazások kapják meg, és mentés után soha nem jelenik meg újra.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Alkalmazások, amelyek valamelyik felhasználó nevében kívánnak eljárni. Minden felhasználó a saját kérelmeit hagyja jóvá. Itt csak akkor utasítson el kérelmet, ha visszaélésnek tűnik; az elutasítás bekerül az auditnaplóba.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Milyen gyakran történjen adatlekérés, és a HR-rendszer saját mezői közül melyek kerüljenek az egyes személyekhez, például költséghely vagy helyszín. A mezők módosítása miatt a következő futás teljes lesz.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'A szervezet informatikai rendszergazdájának átadott, még hozzáférést biztosító hivatkozások. Egy hivatkozás visszavonása azonnal megszünteti a működését; a rajta keresztül már elvégzett beállítások megmaradnak.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Az ügynökök kérelmei, amelyekkel egy felhasználó nevében kívánnak eljárni, beérkezésükkor megjelennek itt. Minden felhasználó a sajátjait hagyja jóvá; ez az oldal a visszaélésnek tűnő kérelmek elutasítására szolgál.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Ha MINDEN feltétel teljesül, a Radar végrehajtja a szabály műveletét, és nem vizsgál további szabályokat. A szabályok kiértékelése az engedélyezési és tiltólisták után, a beépített szabályok előtt történik.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Az alkalmazás által az összes kiszolgált szervezetről küldött auditesemények, a legújabbakkal kezdve. Minden szervezet eseményei saját hashláncot alkotnak.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Minden, amit a szervezet már beállított, és ami még hátravan. A beállítási ellenőrzőlista a tényleges állapotot követi: egy lépés automatikusan késznek jelölődik, amint valóban elkészült.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Rendszergazdaként adjon hozzá hitelesítő alkalmazást vagy hozzáférési kulcsot is. A telefonszám feletti irányítás megszerzésével az SMS-ek is megszerezhetők, ezért nem lehetnek az egyetlen második tényezője.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'A szervezet törlése minden hozzá tartozó projektet és környezetet eltávolít. Az éles identitásszolgáltatók védelme érdekében ez nem önkiszolgáló művelet. A folytatáshoz forduljon az ügyfélszolgálathoz.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Azonnal elveszíti a hozzáférést a telepítés összes platformoldalához, meglévő munkamenetei pedig a következő kérésnél érvénytelenné válnak. Itt újraaktiválhatja.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Az igazolt domainek a felhasználókat az Ön saját identitásszolgáltatójához irányítják; ez az Enterprise csomag része. A szervezet számára való engedélyezéshez forduljon a fiókját kezelő csapathoz.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'A jogosultság egy olyan művelet, amelyet egy szerepkör elvégezhet, például számlák létrehozása vagy jelentések olvasása. Itt kódírás nélkül hozhat létre saját jogosultságokat, majd szerepkörökbe rendezheti őket. Az alkalmazások automatikusan is regisztrálhatják saját jogosultságaikat, így a lista követi a ténylegesen érvényesített szabályokat. A létrehozott jogosultságok az Önéi. A környezet által megosztott jogosultságokat használhatja, de nem módosíthatja.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'A minden bejelentkezéskor érvényes jelszószabályok, zárolás, kétfaktoros hitelesítési és egyszeri bejelentkezési követelmények. A teljes környezetre az is beállítható, hogy elérhetők-e a hozzáférési kulcsok és a bejelentkezési hivatkozások, valamint meddig tart egy munkamenet. A környezet adja meg a minden szervezet által örökölt alapot. A szervezet szigoríthatja a jelszó- és kétfaktoros szabályokat, de nem enyhítheti őket.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Azok a műveletek, amelyekhez a környezet ügynökei emberi jóváhagyásra várnak. Ha az ügynök kulcsa egy művelethez jóváhagyást ír elő, az ügynök megáll, és a kulcs létrehozójának engedélyét kéri. A válasz telefonról vagy itt is megadható. A környezet bármely kezelője elutasíthatja a gyanús kérést. Alattuk a felhasználók nevében eljárni kívánó alkalmazások kérelmei láthatók, amelyeket minden felhasználó maga hagy jóvá.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'A személy munkamenetei és tokenjei visszavonásra kerülnek. Hozzáférési kulcsai, második hitelesítési tényezői, tagságai, szerepkör-hozzárendelései, API-tokenjei, a trezorban tárolt titkai, eszközei és adatainak minden tárolt másolata törlődik. A fiókból csak egy álnevesített, letiltott rekord marad meg. Az innen személyeket szinkronizáló alkalmazások törlési értesítést kapnak. Az auditnapló csak az átlátszatlan azonosítót őrzi meg, a nevet és a címet nem.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Minden, amit Ön jóváhagyott, beleértve azokat az eszközöket és parancssori programokat is, amelyekből bejelentkezett.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Azok az adatok, amelyeket saját rendszereinek ehhez a szervezethez kell tárolniuk. A kulcs nélküli sorok kimaradnak.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'A saját szabályok után kerülnek kiértékelésre. Minden aktiválódó szabályt naplózunk; a legszigorúbb dönt.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'A kézbesítés folytatódik. A szüneteltetés alatt létrejött bejegyzések továbbra is várakoznak, és a következő köteggel kerülnek elküldésre.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'A kézbesítés azonnal leáll, és a tárolt hitelesítő adat megsemmisül. Az auditnapló változatlan marad.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'A Cbox ID és más rendszerek közötti összes kapcsolat egy helyen: egyszeri bejelentkezés, közösségi bejelentkezés, címtár-szinkronizálás és HR-rendszerek, kimenő provisioning, SAML-alkalmazások, webhookok, hookok, naplófolyamok és adatcsatornák. A katalógusból bármelyik beállítása elindítható; minden kártya az adott típus beállítási oldalát nyitja meg. A kapcsolatok listája minden meglévő kapcsolatot és annak állapotát mutatja, a hibásakat elöl.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Minden itteni bejelentkezési mód — jelszó, hozzáférési kulcs, bejelentkezési hivatkozás, közösségi fiók, vállalati SSO és második tényező — az állapotával és a beállítás helyével együtt. A legtöbbről a környezet rendelkezik; az SSO-kapcsolatok az egyes szervezetekhez tartoznak. Ha a telepítés egy módot letiltott vagy korlátozott, az oldal ezt a felelős beállítás megnevezésével jelzi.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Ügynök minden olyan szoftver, amely felügyeleti kulccsal végez műveleteket ebben a környezetben: például Claude Code vagy Cursor AI-asszisztens, belső bot vagy saját háttérrendszer. Mindegyik kapjon külön kulcsot, csak a szükséges hozzáférési körökkel. Határozza meg, mely műveletek várjanak jóváhagyásra, és vonja vissza a kulcsot, amint az ügynök végzett vagy bármi gyanúsnak tűnik.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Az API egy saját szolgáltatás, amely hozzáférési tokeneket fogad, például https://api.example.com. Regisztrálja a szolgáltatás által ismert hozzáférési körökkel, hogy ezeket kioszthassa. Ön dönti el, mely köröket kérhetik a környezet szervezetei által regisztrált alkalmazások. Az API-nak szánt token célközönségként tartalmazza annak címét, amelyet a szolgáltatás ellenőriz.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Az auditnyomvonal kijuttatása a Cbox ID-ból: az ütemezett export ötpercenként elküldi az új bejegyzéseket a SIEM-be vagy az archívumba. A napi megőrzési feladat ellenőrzőpontot hoz létre, adatok törlése nélkül. Itt kérhető le egy személy audittörténete GDPR szerinti hozzáférési kérelemhez, illetve a környezeti konzolban itt ellenőrizhető az exportok működése.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Írja be pontosan a megjelenített szöveget. A(z) „:part1” gomb addig nem használható, amíg a szöveg nem egyezik.',
    'my_part1_app_40bca4ad' => 'Saját :part1 alkalmazás',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Egy folyamatosan futó folyamat, a php artisan queue:autoscale indítja és állítja le a sorban várakozó feladatokat feldolgozó munkafolyamatokat.',
    'this_will_allow_part1_to_6ac64554' => 'A(z) :part1 alkalmazás a következőket teheti:',
    'totp_added_on' => ':date hozzáadva',
