    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Hozzon létre egyet a Platform › Környezetek oldalon, és a hozzá tartozó számlálók itt jelennek meg.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'A telepítés összes környezete és az egyes környezetek részesedése az egészből',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'A telepítés összes háttérfeladat-sora és az egyes sorok legrégebbi feladatának várakozási ideje',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Az időszak összes használati számlálója és a hozzájuk tartozó metrikák eredeti kulcsa',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Keressen szervezetet vagy felhasználót az összes környezetben, ne csak a konzolban éppen kiválasztottban.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Nincs megfelelő igényelt domain. Próbálkozzon a domain egy részével, @ nélkül.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Nincs ilyen nevű kapcsolat. Próbálkozzon másik keresőkifejezéssel.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Nincs ilyen nevű címtár. Próbálkozzon másik keresőkifejezéssel.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Nincs a keresésnek megfelelő végpont-URL. Próbálkozzon másik kereséssel.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Nincs a szűrőknek megfelelő bejegyzés. Próbálkozzon általánosabb kifejezéssel, vagy töröljön egy szűrőt.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Nincs ilyen nevű naplófolyam. Próbálkozzon másik kereséssel.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Nincs ilyen nevű kimenő kapcsolat. Próbálkozzon másik kereséssel.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'A márka minden, felhasználók által látható eleme egy oldalon: a hosztolt bejelentkezési oldal logója, faviconja, színei, betűtípusa és lekerekítései élő előnézettel, valamint a termék neve, az e-mailek feladója és az üdvözlő e-mail. A teljes környezetre egyszer beállított értékeket minden szervezet örökli. Egy szervezet az Arculat lapján külön megjelenést is kaphat.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'A szervezet minden projektjének saját előfizetési csomagja és környezetkerete van. Ezek itt a havi használat mellett láthatók: szervezetek, számlázott egyszeri bejelentkezési kapcsolatok és bejelentkezések. Az ár a havi aktív felhasználókat és az olyan vállalati kapcsolatokat veszi figyelembe, mint az SSO és a SCIM. A tesztkörnyezetekben nincs kapcsolati díj.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'A szervezet tagjai által az alkalmazásaihoz létrehozott összes API-kulcs: tulajdonos, alkalmazás, jogosultságok és utolsó használat. A kulcs csak arra jogosult, amire a tulajdonosa, és a tulajdonos távozásakor működésképtelenné válik. Vonja vissza a kiszivárgott vagy már nem használt kulcsokat. Saját kulcsait mindenki a Saját fiók alatt hozza létre.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Más rendszerből történő átálláskor az alkalmazás kérheti a Cbox ID-ban még nem szereplő személy e-mail-címének és jelszavának ellenőrzését a régi bejelentkezési végponton. Jóváhagyás előtt tesztelje a végpontot. Az elfogadott személy itt létrejön, és többé nem kerül vissza a régi rendszerhez. Ha azonban a régi végpont nem működik, a még át nem költözött személyek nem tudnak bejelentkezni.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Az alkalmazás által a kiszolgált szervezetekről küldött auditesemények: ki, mit és mikor tett a termékben. Az események szervezetenként külön hashláncban tárolódnak, és az adott szervezet rendszergazdái láthatják őket. Akkor használható, ha egy szervezet a fiókja auditnaplóját kéri. Sémák meghatározásával biztosítható az események egységes szerkezete.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Egyetlen jövőbeli ideiglenes hozzáférési engedély sem nyithatja meg ezt a titkot. A visszavonás azonnali és végleges.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Nincsenek aktív ügynökök. A visszavont és lejárt kulcsok nyilvántartási célból a listán maradnak.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Nincsenek jogosultságok — csak a birtokosát azonosítja',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'A bekapcsolásig senki számára nem változik semmi. Először tesztelje a bejelentkezést.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Csak a hash tárolódik. Ha elveszíti a kulcsot, vonja vissza, és hozzon létre újat.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Csak az itt felsorolt alkalmazások kaphatnak ideiglenes hozzáférést ehhez a titokhoz. Minden más kérés elutasításra kerül.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Az összes többi eszközön a következő kéréskor megszűnik az Ön munkamenete. Ezen az eszközön bejelentkezve marad.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'A szervezetnek még nincsenek tagjai. Senki sem jelentkezhet be, amíg valakit meg nem hívnak vagy automatikus felhasználó-létrehozással hozzá nem adnak.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Itt nem kell jelszót megadni. A felhasználó e-mailben bejelentkezési hivatkozást kap, és maga választja ki a bejelentkezés módját.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Minden lépés értékelése az aktuális állapot alapján történik, így az útmutató mindig a szervezet valós helyzetét mutatja.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Másolja ki most a kulcsot, és adja át az ügynöknek. Csak a hash tárolódik, ezért a kulcs csak most látható.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'A szervezet e-mail-domainjei, mindegyik DNS TXT-rekorddal igazolva. Az ellenőrzés után bekapcsolható a kötelező SSO-ra irányítás: az adott domainhez tartozó címmel mindenki a vállalati SSO-kapcsolaton keresztül jelentkezik be jelszó helyett. Az egyszeri bejelentkezésre való áttérés előtt ellenőrizze a felhasználók összes e-mail-domainjét.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Az alkalmazás saját hozzáférési modellje: erőforrástípusok, például dokumentumok és mappák, kapcsolatok, például tulajdonos, szerkesztő és megtekintő, valamint ezek öröklődése. Egy mappa megtekintői például annak minden dokumentumát olvashatják. Az alkalmazás rögzíti, ki melyik erőforráshoz hogyan kapcsolódik, és minden kérésnél ellenőrzi, hogy a felhasználó szerkesztheti-e a dokumentumot. A választ a séma határozza meg.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'A környezet a REST API mellett MCP-szervert is kínál, amelyen keresztül az AI-asszisztensek szabványos módon hívhatnak eszközöket. Illessze be a címet és egy felügyeleti kulcsot a Claude Code, a Cursor vagy más MCP-kliens beállításaiba. Az ügynök pontosan a kulcs hozzáférési körei által engedélyezett műveleteket végezheti el, a konzoléval azonos ellenőrzésekkel és auditnaplóval.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'A kulcs lehetővé teszi, hogy saját szkriptjei és integrációi bejelentkezés nélkül, az Ön nevében hívják egy alkalmazás API-ját. Csak arra jogosult, amire Ön az alkalmazásban: ha az Ön hozzáférése csökken, a kulcsé is csökken. A kulcs csak egyszer jelenik meg. Létrehozáskor másolja ki, kiszivárgáskor vagy a használat befejezésekor pedig azonnal vonja vissza.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Az automatikus felhasználó-szinkronizálás leáll, és a csoportleképezések törlődnek. A létrehozott felhasználók megmaradnak.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Az automatikus felhasználó-szinkronizálás azonnal leáll, és az összes csoportleképezés törlődik. Ez a művelet nem vonható vissza.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'A célalkalmazás automatikus felhasználó-szinkronizálása azonnal leáll. Ez a művelet nem vonható vissza.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'A célalkalmazás automatikus felhasználó-szinkronizálása azonnal leáll. Az ott már létrehozott felhasználók megmaradnak.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'A telefonszám eltávolítva. A felhasználó többi hitelesítési tényezője és helyreállítási kódja változatlan marad.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'A már csatlakozott felhasználók az újracsatlakozásig megtartják az általuk jóváhagyott hozzáférési köröket.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Az eredetek frissítve. A módosítás a következő kérésnél lép életbe.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Más rendszerek is használhatják ezt az értéket. A módosítás megváltoztatja az általuk tárolt URL-eket.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Az erre a szolgáltatóra támaszkodó felhasználók elveszítik ezt a bejelentkezési lehetőséget. Ez a művelet nem vonható vissza.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'A projekt felfüggesztve. Környezetei tovább működnek, de újakat csak a projekt újraaktiválása után lehet hozzáadni.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'A szerepkör-definíció aktiválva. A szerepkör jelenlegi birtokosaira mostantól ezek a jogosultságok érvényesek.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'A szabály aktiválva. Mostantól minden olyan hozzáférés megadása blokkolva lesz, amely megsértené a szabályt.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'A séma mentve. Mostantól e séma alapján ellenőrizzük a művelet eseményeit.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'A séma mentve. Mostantól minden ellenőrzés eredményét ez határozza meg.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'A sémával nem rendelkező műveletek eseményeinek elutasítása. Akkor kapcsolja be, amikor az alkalmazás által küldött összes műveletnek van sémája.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Az objektumok a prefix/yyyy/mm/dd/hh/batch.ndjson.gz útvonalra kerülnek, soronként egy eseménnyel.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Csak S3-kompatibilis tárhelyhez, például MinIO-hoz vagy Cloudflare R2-höz. Üresen hagyva a régió AWS-végpontját használja.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Regisztrálja ezt a szolgáltatónál engedélyezett átirányítási URI-ként, pontosan az itt látható formában.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'A webhookokat, a csatlakoztatott alkalmazások kijelentkezési értesítéseit, az ezekből lekért szerepkör-frissítéseket és a várakozó e-maileket háttérben futó feldolgozók kezelik, nem a felhasználó várakozása közben. Ha nincs futó feldolgozó, semmi nem kerül elküldésre, miközben a konzol többi része hibátlannak látszhat. Ezen az oldalon látható a probléma.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Olyan felülvizsgálat, amelyben ellenőrizhető, ki melyik szerepkört birtokolja, és szüksége van-e még rá. A hozzáférések észrevétlenül felhalmozódnak: a munkatársak csapatot váltanak, de régi jogosultságaik megmaradnak. A felülvizsgálat ezeket segít eltávolítani. A visszavonások a lezáráskor lépnek életbe, a teljes folyamat pedig rögzítésre kerül az auditor számára.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Ha az alkalmazás később más URL-t ad meg, a jóváhagyás megszűnik, és új jóváhagyás szükséges. A jelszavak céljának módosítása nem vehető át észrevétlenül. A delegált bejelentkezés átmeneti megoldás: amikor már kevesen maradnak a régi rendszerben, vonja vissza, és küldjön jelszó-visszaállítást az érintetteknek.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Lehetővé teszi a bejelentkezést meglévő vállalati fiókkal, például Microsoft Entra ID, Okta vagy Google Workspace használatával, külön itteni jelszó helyett. Egyszer kell csatlakoztatni az identitásszolgáltatót és igazolni az e-mail-domaineket. Az ezekhez tartozó felhasználók ezután a szolgáltatóhoz kerülnek bejelentkezéskor.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Minden személy, akinek identitása van ebben a környezetben, a szervezeti tagságtól függetlenül. Egy személy megnyitásával visszaállítható a jelszava vagy második tényezője, lezárhatók a munkamenetei, letiltható a fiókja, módosíthatók a szervezetei és szerepkörei, illetve törlési kérelem esetén véglegesen eltávolíthatók az adatai.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Illessze be a szolgáltató metaadat-XML-jét vagy a metaadatok URL-jét; az alábbi mezők automatikusan kitöltődnek.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Illessze be ezt az identitásszolgáltatónál a csatlakoztatott címtár bearer tokenjével együtt.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Állítsa be ezeket a címeket az OIDC-kliensben. Az automatikus felderítés minden végpontot elérhetővé tesz.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Regisztráljon egy alkalmazást, amely ezt a környezetet használja SAML-identitásszolgáltatóként.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Regisztráljon egyet, hogy az alkalmazás felhasználói a környezetben már meglévő fiókjukkal jelentkezhessenek be.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Csak az itt felsorolt alkalmazások kapnak tokent. Minden más kérés elutasításra kerül.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Ehhez a szervezethez nincsenek funkciójogosultságok beállítva. A telepítés alapértelmezett beállításai érvényesek.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'A célkörnyezet szervezetei felügyeleti fastruktúrában.',
