    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'A teljes platform használata az összes környezetben, nem csak a konzolban éppen kiválasztottban.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'A szervezet-tulajdonosok és üzemeltetők Cbox ID-be történő bejelentkezésének módja a platformkörnyezet konzoljában állítható be.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Ezek a bővítési pontok a művelet közben futnak, nem utána, és válaszuk befolyásolja az eredményt: a végpont adatokat adhat a tokenhez, vagy elutasíthatja a bejelentkezést. Közvetlenül részt vesznek a művelet végrehajtásában, ezért a lassú vagy hibás végpontot a bejelentkező személy is érzékeli.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Az identitásszolgáltató a SCIM szabványon keresztül önállóan létrehozza, frissíti és inaktiválja itt a személyeket. A HR-rendszerben rögzített belépés vagy távozás másodperceken belül eljut az alkalmazásokhoz, hibajegyek és hátrahagyott fiókok nélkül — ami távozáskor különösen fontos.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'A környezetben található szervezetek, felhasználók, egyszeri bejelentkezési kapcsolatok, alkalmazások és felhasználó-szinkronizálások száma, mindegyik a saját oldalára mutató hivatkozással. Az alábbi gyorshivatkozások a leggyakoribb létrehozási műveleteket indítják: szervezet, felhasználó, egyszeri bejelentkezési kapcsolat vagy alkalmazás létrehozását.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'A szerepkör az alkalmazások által értelmezett feladatkört jelöl, például „Szerkesztő” vagy „Ügyfélszolgálati munkatárs”. Itt állítható be, ki milyen szerepkört kap; az egyes alkalmazások maguk határozzák meg a szerepkör jogosultságait. A szerepkörök minden csatlakoztatott alkalmazásba követik a személyt, így a hozzáférés egy helyen adható meg és vonható vissza.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Minden auditnapló-bejegyzést a rögzítésekor átmásol a biztonsági csapat eszközeibe, például egy SIEM-rendszerbe. Állítson be egy célhelyet, hogy a vizsgálat a már használt eszközökben indulhasson, exportálási kérelem nélkül. A kézbesítés legalább egyszer történik meg, ezért előfordulhatnak ismétlődő bejegyzések.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Amint valaki regisztrál, itt megjelenik a szervezete. Az új szervezetet a fenti Új szervezet gombbal is létrehozhatja.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Adja hozzá a szervezet tagjainak e-mail-címeiben használt domaint, tegye közzé a TXT-rekordot, és ellenőrizze a domaint.',
