    'replace_the_sealed_value_with_a_new_credential_the_stor_17b46d38' => 'Cserélje le a titkosított értéket egy új hitelesítő adatra. A tárolt érték soha nem jelenik meg.',
    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'Mentéskor azonnal titkosítjuk, és többé nem jelenik meg. Ha szüksége van rá, őrizzen meg egy másolatot.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Titkosítva tároljuk, és többé nem jelenik meg. Hagyja üresen a jelenlegi érték megtartásához.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'A titok lecserélve, a korábbi már nem működik. Másolja ki most az újat, mert többé nem jelenik meg.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'A visszavonás azonnali és végleges. Egyetlen jövőbeli ideiglenes hozzáférési engedély sem nyithatja meg ezt a titkot.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'A metaadatsémák a JSON Schema részhalmazát alkotják: olyan objektumok, amelyek tulajdonságai karakterláncok, számok, egész számok, logikai értékek vagy null értékűek lehetnek, felsorolási, hossz-, tartomány-, minta- és formátumkorlátozásokkal. A módosítás mentése új verziót hoz létre; a korábban rögzített események megőrzik az ellenőrzésükkor használt verziót.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Minden kapcsolat lehetővé teszi egy saját fiók csatlakoztatását egy szolgáltatáshoz, például a GitHubhoz, a Google-höz vagy a Slackhez. A tokeneket itt titkosítva tároljuk és frissítjük. Az engedélyezett alkalmazások minden alkalommal érvényes tokent kérnek, amikor a személy nevében hívják a szolgáltatást; maguk nem tárolnak tokeneket.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Az adminisztrációs és támogatási szerepkört saját munkatársainak, például az ügyfélszolgálati vagy üzemeltetési csapatnak adhatja meg az egész környezetre. Minden szervezetben érvényes, és a szervezetek adminisztrátorai nem láthatják, nem adhatják meg és nem vonhatják vissza. Egy alkalmazás saját szerepköre így megadva is csak arra az alkalmazásra érvényes.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'A környezet teljesen elkülönített identitásszolgáltatás saját felhasználókkal, kulcsokkal, bejelentkezéssel és kibocsátóval. Itt a telepítés minden környezete megjelenik a tulajdonos szervezetével együtt. Hozzon létre egyet, válassza ki a konzolban, majd adja hozzá az első szervezetet és adminisztrátort.',
