    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'A szervezet egy regisztrált vállalat saját területe ezen a telepítésen, a projektjeivel, környezeteivel és csapatával. Nyissa meg a termékek és környezetek áttekintéséhez, vagy függessze fel: ez kijelentkezteti a tagokat, és minden hozzá tartozó környezetben leállítja a bejelentkezést.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Amikor egy alkalmazásnak vagy AI-ügynöknek engedélyre van szüksége, hogy az Ön nevében járjon el, nem mindig tudja azt az Ön előtt lévő képernyőn kérni — ezért itt kéri. Csak saját maga által indított kérelmeket hagyjon jóvá, és ellenőrizze, hogy a megjelenített kód egyezik-e a kérelmező eszközön láthatóval.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'A projekt az Ön egyik termékét jelenti, saját csomaggal, bejelentkezéssel és például éles vagy előkészítő környezetekkel. Itt nyithat meg egy környezetet az adminisztrálásához. Hozzon létre új projektet, amikor önállóan számlázandó és működtetendő terméket indít.',
