    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'A bucket a gépnév helyett az elérési útban szerepel. Az egyéni végpont már ezt a formátumot használja.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Minden alkalmazás, amely a Cbox ID-n keresztül jelentkeztet be személyeket vagy annak API-ját hívja, itt kerül regisztrálásra, és saját hitelesítő adatokat kap. Alkalmazásonként és környezetenként külön regisztrációt hozzon létre. A hitelesítő adatokat ne ossza meg közöttük, így az egyik visszavonása nem állítja le a többit.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Szervezetet keres név vagy azonosító, felhasználót pedig név vagy e-mail-cím alapján a telepítés összes környezetében, nem csak a konzolban kiválasztottban. Akkor használja, ha valaki segítséget kér, és nem tudja, melyik környezethez tartozik.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Pontosan úgy láthatja az alkalmazást, mint annak egyik felhasználója: megadott indokkal, legfeljebb egy órára bejelentkezhet a nevében. Az alkalmazás értesül a ténylegesen eljáró személyről, és nem kap lehetőséget a munkamenet fenntartására. A szervezet auditnaplója rögzíti, ki és miért tette ezt.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'A projekt a szervezet egyik IdP-terméke, amelyhez a környezetek tartoznak. Amíg a szervezet nem hoz létre projektet a saját konzoljában, itt nincs kiválasztható vagy megnyitható környezet. Ezen a képernyőn nem lehet projektet létrehozni a szervezet nevében.',
