    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Minden szervezet a terméket használó vállalatot vagy csapatot jelöl, saját tagokkal, szerepkörökkel, domainekkel és egyszeri bejelentkezéssel. Minden regisztráló vállalatnak hozzon létre egyet. Nyissa meg a tagok, meghívók és igazolt domainek kezeléséhez vagy a szervezet felfüggesztéséhez.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'A Cbox ID aláírt üzenetet küld a végpontjára, miután valami történt, például csatlakozott egy tag vagy megváltozott egy szerepkör. Így rendszerei rendszeres lekérdezés nélkül reagálhatnak. A sikertelen kézbesítést újrapróbáljuk. Az esemény már megtörtént: a végpont értesítést kap, de az eredményről nem dönthet.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'A séma meghatározza egy művelet eseményeinek szerkezetét: milyen céltípusokat neveznek meg, és mit tartalmaznak a metaadataik. A sémával rendelkező műveletek eseményeit érkezéskor ellenőrizzük. Séma nélkül változatlanul elfogadjuk őket, kivéve, ha a szigorú mód be van kapcsolva.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'A szervezet összes adminisztrátora, beépített szerepkörük — Tulajdonos, Adminisztrátor, Fejlesztő, Tag vagy Megtekintő — és az általuk elérhető környezetek. Hívjon meg személyeket e-mailben, és mindenkinek csak a munkájához szükséges környezeteket engedélyezze.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Engedje meg az alkalmazások felhasználóinak saját GitHub-, Google-, Slack- vagy Salesforce-fiókjuk csatlakoztatását, hogy az alkalmazások a nevükben hívhassák ezeket az API-kat. Tokenjeiket itt titkosítva tároljuk és frissítjük; ideiglenesen csak az engedélyezett alkalmazások kapják meg őket.',
