    'platform_operators_administer_every_organization_and_en_36866fb1' => 'A platformüzemeltetők a telepítés összes szervezetét és környezetét kezelik, az egyes szervezetek feletti szinten. Csak a telepítés működtetéséért felelős személyt adjon hozzá üzemeltetőként, és függessze fel, amint ez már nem a feladata.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'A konzolban kiválasztott környezet összes szervezete, a viszonteladók, az általuk kezelt szervezetek és azok alegységeinek faszerkezetében. Itt szervezetet hozhat létre, függeszthet fel vagy helyezhet át másik szülőszervezet alá.',
