    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'A szervezet minden módosítása: ki, mit, melyik objektumon és mikor végzett. A bejegyzéseket hash-lánc köti össze, ezért egy bejegyzés törlése vagy módosítása megtöri a láncot és észlelhetővé válik. Szándékosan csak olvasható — ezt a nyilvántartást adhatja át az auditornak.',
