    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Ez a környezet a REST API mellett MCP-kiszolgálót is biztosít. Csatlakoztasson hozzá ügynököt egy kezelési kulccsal, és az pontosan a kulcs hatókörei által engedélyezett műveleteket végezheti el, a konzoléval azonos ellenőrzésekkel, jóváhagyásokkal és auditnaplóval.',
