    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1: egy termék saját identitásszolgáltatója, önálló csomag szerinti számlázással. Elkülönített éles és tesztkörnyezeteket fog össze (:part2 :part3), saját felhasználókkal, kulcsokkal és bejelentkezéssel.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'A szervezeti kulcs magát a szervezetet éri el — projekteket, környezeteket, csapatot és kulcsokat —, nem a környezetek belsejét. A platform legfelső szintjén hozható létre itt: :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Alkalmazások, amelyek megbíznak ebben a környezetben mint SAML-identitásszolgáltatóban. Más szolgáltatásnál meglévő fiókkal való bejelentkezéshez használja ezt: :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'A jóváhagyások a kezelési API műveleteire vonatkoznak. Ezeket a hatóköröket olyan végpontok szolgálják ki, amelyek még nem műveletek, ezért jóváhagyáskérés nélkül futnak: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Az API-val azonos tulajdonosú alkalmazást kapcsoljon hozzá. Az API tokenjei a kapcsolt alkalmazás szerepköreit és jogosultságait tartalmazzák, ezért az alkalmazásnak ugyanahhoz a tulajdonoshoz kell tartoznia.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Nincs beállítva — a Radar továbbra is blokkolhat, de nem kérheti annak igazolását, hogy a felhasználó ember. A megjelölt regisztrációnál ehelyett az e-mail-címet kell megerősíteni.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Válassza ki az auditnyomvonal célját — Splunk, Elastic, Graylog, CEF vagy bármely JSON-gyűjtő, Datadog, illetve saját Amazon S3- vagy Google Cloud Storage-tároló.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'A személy számára a bejelentkezéskor kiválasztott szervezetben bekapcsolt funkciókapcsolók kulcsait `feature_flags` állításként elhelyezi a hozzáférési tokenben, az ID-tokenben és a UserInfo-válaszban.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'A személy SZEREPKÖREIT `groups` néven helyezi el az ID-tokenben — ezt keresi a Kubernetes, a Grafana, a Vault és a legtöbb régebbi SaaS. Ebben a konzolban nincs csoport nevű objektum: hozzon létre egy szerepkört az alkalmazás által várt névvel, és az itt megjelenik.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Regisztráljon egy alkalmazást, hogy munkatársai az itteni fiókjukkal jelentkezhessenek be. Ettől a lépéstől válik a Cbox ID ténylegesen használt szolgáltatássá.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Ez a webhelyikon nem használható. Magát a képet küldje el base64 data: URI formában (data:image/png;base64,…). Távoli kép-URL nem fogadható el: a bejelentkezési oldal képét minden látogató letölti, így egy külső URL felfedné a kiszolgálójának, kik a látogatók.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Ez a logó nem használható. Magát a képet küldje el base64 data: URI formában (data:image/png;base64,…). Távoli kép-URL nem fogadható el: a bejelentkezési oldal képét minden látogató letölti, így egy külső URL felfedné a kiszolgálójának, kik a látogatók.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'A cím Tor-kilépőcsomópont, VPN vagy nyílt proxy. A Tort a helyi kilépőlista alapján azonosítjuk; a VPN-hez és a proxyhoz ezeket jelző IP-információs szolgáltatás szükséges.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'A gomb eltűnik a környezet minden olyan bejelentkezési oldaláról, amely örökli. A hitelesítő adatai megmaradnak, így újra bekapcsolhatja.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'A gomb eltűnik a szervezet bejelentkezési oldaláról — a környezet saját gombja nem lép a helyébe. A hitelesítő adatai megmaradnak, így újra bekapcsolhatja.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'A konzol erre a környezetre vált, és minden ezután megnyitott oldal ezt olvassa a jelenlegi helyett. Egyik környezetben sem változik semmi.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'A bejelentkezési oldal az Ön szervezetének arculatát használja: logót, színeket és szövegezést. A változások élő előnézetben látszanak, és a szervezet hosztolt bejelentkezési oldalára érvényesek.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Ez a hitelesítő adat emberi jóváhagyást igényel ehhez a művelethez, de nincs rögzítve jóváhagyó személy. Futtassa a konzolból, vagy hozzon létre kulcsot a konzolban, hogy a tulajdonosa jóváhagyhassa.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'A környezet visszaáll az alapértelmezett domainjére. A jelenlegi kibocsátóhoz, felderítési URL-hez vagy JWKS URL-hez kötött minden kliens működése leáll, amíg át nem állítják.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Az e-mailt most nem sikerült elküldeni — a telepítés nem éri el a levelezőszerverét. Próbálja később; egy rendszergazda a `php artisan cbox-id:users:confirm-email` paranccsal is megerősítheti a címét.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'A bejelentkezési oldal az Ön logóját és színeit viseli. Az emberek jelszót írnak bele — Önt kell felismerniük rajta, nem minket.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Az alkalmazás létrehozásakor egy titkos klienskulcs készül, amely a következő képernyőn csak egyszer jelenik meg. Ezzel lehet az alkalmazás nevében bejelentkezni, amíg új kulcsra nem cserélik.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Az alkalmazás regisztrálásakor létrejön egy kliens-titok, amely csak egyszer, a következő képernyőn jelenik meg. A cseréjéig ezzel lehet az alkalmazás nevében hitelesíteni.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'Ebben a projektben nincs másik környezet, amelyet Ön kezel. Adjon egyet a projekthez, vagy kérjen hozzáférést, és megjelenik itt.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Ez az alkalmazás egy szervezethez tartozik, egy szervezet pedig csak egy környezetben létezik. Töltse le a tervét, és regisztrálja a másik környezetben az ottani szervezete alatt.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Ez az alkalmazás saját magát regisztrálta, ezért nem a környezet saját alkalmazásai közé tartozik. Ugyanígy regisztrálhatja magát a másik környezetben is.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Ez az alkalmazás saját kulcsokkal jelentkezik be, és minden környezetnek saját kulcsokkal kell rendelkeznie. Töltse le a tervét, és regisztrálja a másik környezetben annak kulcskészletével.',
    'app_keys_unavailable_organization_switch' => 'Az alkalmazás, amely ide irányította, nem kínál API-kulcsokat a(z) :organization szervezethez. Próbáljon másik szervezetet, vagy forduljon az alkalmazás ügyfélszolgálatához.',
    'app_keys_unavailable_organization' => 'Az alkalmazás, amely ide irányította, nem kínál API-kulcsokat a(z) :organization szervezethez. Forduljon az alkalmazás ügyfélszolgálatához.',
    'app_keys_unavailable_switch' => 'Az alkalmazás, amely ide irányította, nem kínál API-kulcsokat. Próbáljon másik szervezetet, vagy forduljon az alkalmazás ügyfélszolgálatához.',
    'app_keys_unavailable' => 'Az alkalmazás, amely ide irányította, nem kínál API-kulcsokat. Forduljon az alkalmazás ügyfélszolgálatához.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Egyszer csatlakozzon a platform legfelső szintjén, ne környezetenként. Az Ön nevében bejelentkezett ügynök eléri a szervezetét, annak minden Ön által kezelt környezetét és a saját fiókját. A környezeti eszköz :part1 :part2 argumentuma, a REST API esetén pedig a :part3 fejléc jelöli a művelet helyét. Az ügynök az Ön jogosultságaival, az engedélyezett keretek között járhat el, és minden kritikus művelet az eszközén adott jóváhagyásra vár.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Minden szervezet egy szerepet ad ebből a típusból: :part1. Ez határozza meg, mit adminisztrálhat a személy. Az alkalmazásokban végezhető műveleteket pedig tetszőleges számú ilyen szerepkör szabályozza: :part2.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'A(z) „:part1” környezet létrejött. A környezet domainbeállításaiban adja hozzá ezt a domaint DNS-ellenőrzéshez: :part2. Nem igazolt domain nem lehet a környezet kibocsátója.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'A környezetek projekthez tartoznak, a projektek pedig szervezethez (:part1 :part2 :part3). Ott tekintheti át a teljes szervezetet. Kétféle bejegyzéshez soha nem tartozik szervezet: a(z) :part4 maga a telepítés környezete, amely az üzemeltetőket és a szervezetek saját személyeit tárolja; a(z) :part5 :part6 jelölésű környezethez nincs projekt, ezért nem számlázódik, és egyik szervezet sem éri el. Egyik eset sem itt javítandó hiba, és ezen a képernyőn nem rendelhetők át.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'A(z) :part1 összes bejelentkezési módja, azok állapota és módosításuk helye. A szervezetek szigoríthatják a szabályokat: :part2 :part3.',
    'no_applications_match_part1_try_a_different_entity_id_386ed821' => 'Nincs a(z) „:part1” keresésnek megfelelő alkalmazás. Próbáljon másik entitásazonosítót.',
    'no_organizations_match_part1_try_a_different_name_or_ha_72ccc404' => 'Nincs a(z) „:part1” keresésnek megfelelő szervezet. Próbáljon másik nevet vagy azonosítót.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'A végpont ezzel a titkos kulccsal ellenőrzi minden kérés :part1 fejlécét.',
    'ask_an_owner_of_the_organization_to_give_you_access_to__74d808e8' => 'Kérjen hozzáférést a szervezet egyik tulajdonosától ehhez a környezethez: :part1.',
    'hand_it_to_part1_over_a_channel_you_trust_we_never_stor_205e825e' => 'Adja át a jelszót a(z) :part1 felhasználónak megbízható csatornán. Olvasható formában soha nem tároljuk.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'A felhasználóknak megjelenő sorrendben. A környezet egyik szolgáltatójának itteni kikapcsolása csak a gombot távolítja el erről az oldalról; másutt nem akadályozza meg az adott bejelentkezést. Ha kizárólag a saját szolgáltatóját szeretné engedni, tegye kötelezővé az SSO-t itt: :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Az érintett személyek (:part1) többé nem jelentkezhetnek be ebbe a szervezetbe, és az arra támaszkodó alkalmazások sem hitelesítik őket. Az alszervezetek nem lesznek felfüggesztve. A szervezet itt újraaktiválható.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'A kulcsok ezzel az előtaggal kezdődnek, így a naplóban talált kulcs azonosítja az alkalmazást: :part1 :part2. Használjon 2–16 kisbetűt vagy számjegyet, majd :part3 vagy :part4 :part5 utótagot, a környezetben egyedi értékkel. A megadás engedélyezi a kulcsokat; az ürítés az újakat tiltja, a meglévők visszavonásig működnek.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'A szervezetben még senki sem hozott létre kulcsot az alkalmazásokhoz. A személyek a Saját fiók alatt készíthetik el saját kulcsaikat olyan alkalmazáshoz, amely a Beállításokban engedélyezi a tagi API-kulcsokat: :part1.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Illessze be annak a szolgáltatásfióknak a teljes JSON-kulcsfájlját, amely a buckethez roles/storage.objectCreator szerepkört kapott. Titkosítva tároljuk, és többé nem jelenítjük meg. :part1',
    'approved_part1_last_used_part2_part3_e3a21893' => 'Jóváhagyás: :part1 · Utolsó használat: :part2 :part3',
    'connected_part1_part2_part3_part4_a093c4a3' => 'Csatlakoztatva: :part1 :part2 :part3 :part4',
    'add_this_dns_part1_record_at_your_domain_then_verify_it_3d494578' => 'Adja hozzá ezt a :part1 típusú DNS-rekordot a domainhez, majd indítsa el az ellenőrzést. Ezzel igazolja, hogy rendelkezik a(z) :part2 domain felett.',
    'confirm_your_email_address_part1_to_make_changes_in_the_7b9d8809' => 'A konzolban végzett módosításokhoz erősítse meg e-mail-címét: :part1.',
    'the_new_key_for_part1_copy_it_now_you_won_t_be_able_to_42e3ecb3' => 'A(z) :part1 ügynök új kulcsa. Másolja ki most, mert később már nem tekinthető meg.',
    'bootstrap_part1_first_organization_admin_7459ca65' => 'A(z) :part1 kezdeti beállítása — az első szervezet és adminisztrátor',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Az egész környezetben, minden szervezetben érvényes szerepkörök, akkor is, ha a személy egyik szervezethez sem tartozik. A szervezetek ezeket soha nem látják. :part1 :part2',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Jelentkezzen be egy alkalmazásba :part1 nevében, hogy ugyanazt lássa. Az alkalmazás értesül arról, hogy valójában Ön jár el, a szervezet auditnaplója pedig rögzíti a személyt, az időpontot és az indokot.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Ha valaki bejelentkezik, és rá ez érvényes: :part1, az e-mail-címét és jelszavát elküldjük a végpontnak. Ha a végpont elfogadja, itt létrejön a személy, és adatait többé nem küldjük oda.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Elakadt valamelyik lépésnél? A konzol minden oldalának címe mellett található egy :part1 :part2 :part3 ikon rövid magyarázattal és a teljes útmutatóra mutató hivatkozással.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Itt kizárólag felfüggesztés végezhető, amely visszavonható. Ez a képernyő nem töröl szervezetet vagy annak adatait véglegesen. A telepítés szervezethez nem tartozó környezeteket is tartalmaz: a platform gyökérkörnyezetét és a hozzárendeletlen környezeteket. Mindkettő egyértelműen jelölve van itt: :part1 :part2.',
    'agent_revoke_descendant_count' => 'Az ügynök működése azonnal leáll. Az általa kiadott kulcsok is visszavonásra kerülnek (összesen: :count). Ez nem vonható vissza.',
    'open_the_console_of_part1_the_platform_s_own_environmen_37fd9a5c' => 'A platform saját környezete, :part1 konzoljának megnyitása',
    '_part1_manage_your_own_security_under_part2_part3_a21c8866' => ':part1 Saját fiókja biztonságát itt kezelheti: :part2 «:part3».',
    '_part1_part2_to_open_an_environment_you_do_administer_4755ab7d' => 'A saját kezelésű környezet megnyitásához válassza ezt: :part1 :part2.',
    'new_part1_credentials_checked_against_part2_before_the_a56c958b' => 'Új hitelesítő adatok a(z) :part1 szolgáltatáshoz. A rendszer a jelenlegiek cseréje előtt ellenőrzi őket a(z) :part2 szolgáltatónál.',
    'to_answer_a_right_to_erasure_request_use_part1_at_the_f_536cbf09' => 'A törléshez való jog érvényesítésére irányuló kérelem teljesítéséhez használja inkább a lap alján található «:part1» lehetőséget.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'A(z) :part1 számára küldött SMS-kódok többé nem működnek. A hitelesítő alkalmazást, hozzáférési kulcsokat és helyreállítási kódokat ez nem érinti. Ha a telefonszám volt az egyetlen második tényező, új regisztrációig a fiókot csak a jelszó védi.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'A lista elkészült. Mostantól főként ellenőrzés céljából érdemes visszatérni a konzolba. Két területet célszerű rendszeresen áttekinteni: :part1 :part2 :part3 és :part4 :part5 :part6.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'A szervezetei által igényelt e-mail-domainek. Az igazolt domain minden hozzá tartozó címmel rendelkező személyt a szervezet következő kapcsolatához irányít: :part1 :part2. Minden domain a saját szervezetének oldalán igazolható.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Először frissítse a fogadó rendszert: a következő kísérlettől minden olyan kézbesítést elutasít, amelyet nem tud ellenőrizni.',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'A tesztkörnyezetek engedélyezik a localhost URL-eket, és soha nem küldenek valódi e-maileket. A projekt csomagjában még létrehozható környezetek száma: :part1.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_5da64a1a' => 'A(z) :part1 összes bejelentkezési módja, engedélyezett állapotuk és a módosításuk helye.',
